trigger CaseTrigger on Case (after update) {
    List<Id> newlyClosedCaseIds = new List<Id>();

    for (Case currentCase : Trigger.new) {
        Case previousCase = Trigger.oldMap.get(currentCase.Id);

        if (currentCase.IsClosed &&
            !previousCase.IsClosed &&
            currentCase.ContactId != null) {
            newlyClosedCaseIds.add(currentCase.Id);
        }
    }

    /*
     * A transaction can enqueue only 50 Queueable jobs, but an update trigger
     * can receive 200 Cases. Therefore, enqueuing one job per Case is not
     * bulk-safe. A single job receives all eligible Case IDs and uses partial
     * DML so a Task failure for one Case does not roll back the other Tasks.
     */
    if (!newlyClosedCaseIds.isEmpty()) {
        System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds));
    }
}
