public class CaseSurveyJob implements Queueable, Database.AllowsCallouts {
    private List<Id> caseIds;

    public CaseSurveyJob(Id caseId) {
        this.caseIds = new List<Id>();

        if (caseId != null) {
            this.caseIds.add(caseId);
        }
    }

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds == null
            ? new List<Id>()
            : new List<Id>(caseIds);
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
            AND ContactId != null
        ];

        List<Task> surveyTasks = new List<Task>();

        for (Case caseRecord : cases) {
            surveyTasks.add(new Task(
                WhatId = caseRecord.Id,
                WhoId = caseRecord.ContactId,
                Subject = 'CSAT survey: ' + caseRecord.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status = 'Not Started'
            ));
        }

        if (surveyTasks.isEmpty()) {
            return;
        }

        Database.SaveResult[] results = Database.insert(surveyTasks, false);

        for (Integer index = 0; index < results.size(); index++) {
            if (!results[index].isSuccess()) {
                for (Database.Error error : results[index].getErrors()) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'Failed to create a CSAT survey Task for Case ' +
                        surveyTasks[index].WhatId +
                        '. Status code: ' + error.getStatusCode() +
                        '. Message: ' + error.getMessage()
                    );
                }
            }
        }
    }
}
